<?php
namespace Modules\Analytics\Controllers\Web;
use Core\http\ResponseFactory;use Modules\Analytics\Services\AdminMessageService;use RuntimeException;
class AdminMessageController{public function __construct(private AdminMessageService$service){}public function index(){return$this->run(fn()=>['success'=>true,'data'=>$this->service->index((int)auth()->id())]);}public function store(){return$this->run(fn()=>['success'=>true,'data'=>['id'=>$this->service->send((int)auth()->id(),$this->payload())]]);}public function read(int$id){return$this->run(function()use($id){$this->service->markRead((int)auth()->id(),$id,true);return['success'=>true];});}public function unread(int$id){return$this->run(function()use($id){$this->service->markRead((int)auth()->id(),$id,false);return['success'=>true];});}public function delete(int$id){return$this->run(function()use($id){$this->service->delete((int)auth()->id(),$id);return['success'=>true];});}private function payload():array{$raw=base64_decode(strtr((string)request()->input('payload_b64',''),'-_','+/'),true);$data=$raw===false?null:json_decode($raw,true);if(!is_array($data))throw new RuntimeException('اطلاعات پیام معتبر نیست.');return$data;}private function run(callable$c){try{return ResponseFactory::json($c());}catch(\Throwable$e){return ResponseFactory::json(['success'=>false,'message'=>$e->getMessage()],422);}}}
